<?php
require '/app/harness.php';$GLOBALS['plugin_config']='/encryption-config/director.cfg';
function encIdentity($name,$guid){expectProcess('zfs',['list','-H','-p','-o','name,type,guid','-t','filesystem,volume,snapshot',$name],"$name\tfilesystem\t$guid");}
function encRoot(){expectProcess('zfs',['list','-H','-o','name','-t','filesystem','cache/secure'],'cache/secure');expectProcess('zfs',['get','-H','-o','property,value','encryption,encryptionroot,keystatus','cache/secure'],"encryption\taes-256-gcm\nencryptionroot\tcache/secure\nkeystatus\tunavailable");encIdentity('cache/secure','100');}
function encMountState($name,$mounted){expectProcess('zfs',['get','-H','-o','property,value','encryptionroot,mounted',$name],"encryptionroot\tcache/secure\nmounted\t$mounted");}
function encRecord(){return ['version'=>1,'root'=>'cache/secure','root_guid'=>'100','phase'=>'locked','mounts'=>[['name'=>'cache/secure','guid'=>'100'],['name'=>'cache/secure/child','guid'=>'101']]];}
check('unlock restores exactly recorded GUIDs in parent before child order',function(){zfsmSaveEncryptionState(encRecord());encRoot();expectProcess('zfs',['load-key','-L','prompt','cache/secure']);foreach(['cache/secure'=>'100','cache/secure/child'=>'101'] as $name=>$guid){encIdentity($name,$guid);encMountState($name,'no');expectProcess('zfs',['mount',$name]);encMountState($name,'yes');}same([],unlockDataset('cache/secure','fixture-passphrase')['failed']);same(false,is_file(zfsmEncryptionStateFile('100')));});
check('legacy unlock loads only the key when previous mount states are unknown',function(){encRoot();expectProcess('zfs',['load-key','-L','prompt','cache/secure']);$r=unlockDataset('cache/secure','fixture-passphrase');same([], $r['failed']);same(true,str_contains(implode(' ',$r['succeeded']),'mount state unavailable'));});
check('changed descendant identity retains mount journal and never mounts replacement',function(){zfsmSaveEncryptionState(encRecord());encRoot();expectProcess('zfs',['load-key','-L','prompt','cache/secure']);encIdentity('cache/secure','100');encMountState('cache/secure','yes');encIdentity('cache/secure/child','999');$r=unlockDataset('cache/secure','fixture-passphrase');same(true,(bool)$r['failed']);same('restore_required',zfsmReadEncryptionState('cache/secure','100')['phase']);});
check('encryption journal rejects independent or outside mount targets',function(){$r=encRecord();$r['mounts'][]=['name'=>'cache/elsewhere','guid'=>'999'];try{zfsmSaveEncryptionState($r);throw new LogicException('Expected rejection');}catch(InvalidArgumentException $e){}});
check('partial mount failure keeps the journal and retry skips already restored parent',function(){
 $record=encRecord();zfsmSaveEncryptionState($record);encIdentity('cache/secure','100');encMountState('cache/secure','yes');encIdentity('cache/secure/child','101');encMountState('cache/secure/child','no');expectProcess('zfs',['mount','cache/secure/child'],'permission denied',1);$failed=zfsmRestoreSavedEncryptionMounts($record);same(true,(bool)$failed['failed']);$retained=zfsmReadEncryptionState('cache/secure','100');same('restore_required',$retained['phase']);
 encIdentity('cache/secure','100');encMountState('cache/secure','yes');encIdentity('cache/secure/child','101');encMountState('cache/secure/child','no');expectProcess('zfs',['mount','cache/secure/child']);encMountState('cache/secure/child','yes');same([],zfsmRestoreSavedEncryptionMounts($retained)['failed']);same(false,is_file(zfsmEncryptionStateFile('100')));
});
finishTests();
